      ]
    },
    {
      id: "p3", title: "阶段 3 · 不可逆拆除",
      steps: [
        {
          id: "s5", irreversible: true, windowSec: 60,
          title: "吊销 orders-primary 访问凭据",
          desc: "吊销所有仍指向 orders-primary 的服务账号凭据。",
          why: "凭据吊销切断了旧库的最后一条常规访问路径，防止切流遗漏的服务继续写入。",
          actionLabel: "吊销凭据",
          consequences: [
            "所有仍配置 orders-primary 凭据的服务立即断连",
