  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  background: var(--ok-dim); border: 1px solid var(--ok); border-radius: var(--radius-sm);
  padding: 12px 16px; margin: 0 0 24px; font-size: 14.5px; max-width: 760px;
}
.readonly-note { background: var(--panel-2); border-color: var(--border); }
.done-badge {
  flex: none; background: var(--ok); color: #04160c; font-size: 12px; font-weight: 700;
  letter-spacing: 0.1em; border-radius: 4px; padding: 2px 8px;
}
.record { margin: 0 0 20px; max-width: 760px; }
.record-title { font-size: 13px; color: var(--muted); letter-spacing: 0.08em; margin-bottom: 6px; }
.record-list { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--border-soft); }
.record-list li {
  display: flex; gap: 14px; padding: 7px 2px; border-bottom: 1px solid var(--border-soft);
  font-size: 14px; color: var(--text);
}
.record-t { font-family: var(--mono); color: var(--muted); flex: none; font-size: 13px; padding-top: 1px; }

/* 完成摘要 */
.summary-hero { margin-bottom: 22px; }
.summary-check {
  width: 64px; height: 64px; border-radius: 50%; background: var(--ok); color: #04160c;
  display: flex; align-items: center; justify-content: center; font-size: 34px; font-weight: 800;
  margin-bottom: 18px;
}
.stat-row { display: flex; gap: 16px; flex-wrap: wrap; margin: 0 0 26px; }
.stat {
  background: var(--panel-2); border: 1px solid var(--border-soft); border-radius: var(--radius-sm);
  padding: 14px 20px; min-width: 150px;
}
.stat-num { font-family: var(--mono); font-size: 26px; font-weight: 700; color: var(--accent); }
.stat-label { font-size: 13px; color: var(--muted); margin-top: 2px; }
.summary-irv { list-style: none; margin: 0; padding: 0; }
.summary-irv li { display: flex; align-items: center; gap: 10px; padding: 7px 2px; font-size: 14.5px; border-bottom: 1px solid var(--border-soft); }

/* ---------- 按钮 ---------- */
.btn {
  font: inherit; font-size: 15px; font-weight: 600; cursor: pointer;
  border-radius: var(--radius-sm); padding: 10px 20px; border: 1px solid transparent;
  transition: filter 0.15s ease, background 0.15s ease;
}
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn-sm { font-size: 13.5px; padding: 6px 14px; }
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:not(:disabled):hover { filter: brightness(1.12); }
.btn-danger { background: var(--danger-strong); color: #fff; }
.btn-danger:not(:disabled):hover { filter: brightness(1.12); }
.btn-danger-outline { background: transparent; color: var(--danger); border-color: var(--danger-strong); }
.btn-danger-outline:not(:disabled):hover { background: var(--danger-dim); }
.btn-undo { background: transparent; color: var(--warn); border-color: var(--warn); }
.btn-undo:not(:disabled):hover { background: rgba(255, 200, 87, 0.16); }
.btn-keep { background: var(--warn); color: #201a05; }
.btn-keep:not(:disabled):hover { filter: brightness(1.08); }
.btn-ghost { background: transparent; color: var(--muted); border-color: var(--border); }
.btn-ghost:not(:disabled):hover { color: var(--text); background: var(--panel-2); }

:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* 空态 */
.empty-state { padding: 80px 20px; text-align: center; color: var(--muted); }
.noscript { padding: 40px; text-align: center; color: var(--text); }

@media (max-width: 960px) {
  .layout { grid-template-columns: 1fr; }
  .rail { position: static; }
  .detail { padding: 24px 20px 28px; }
}

