.app { max-width: 1240px; margin: 0 auto; padding: 20px 28px 64px; }

/* ---------- 顶栏 ---------- */
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 20px; padding: 14px 0 10px; flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.brand-mark {
  font-family: var(--mono); font-weight: 700; letter-spacing: 0.18em;
  color: var(--accent); font-size: 14px; border: 1px solid var(--accent);
  border-radius: 6px; padding: 2px 8px;
}
.brand-title { font-size: 19px; font-weight: 650; }
.chip {
  font-family: var(--mono); font-size: 12.5px; padding: 3px 10px;
  border: 1px solid var(--border); border-radius: 999px; color: var(--text);
  background: var(--panel);
}
.chip-dim { color: var(--muted); }
.top-right { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
