  width: 180px; height: 8px; background: var(--panel-2);
  border-radius: 999px; overflow: hidden; border: 1px solid var(--border-soft);
}
.progress-bar { height: 100%; background: var(--accent); border-radius: 999px; transition: width 0.4s ease; }
.progress-text { font-family: var(--mono); font-size: 13.5px; color: var(--text); }
.elapsed { font-size: 13.5px; color: var(--muted); font-family: var(--mono); }

.brief { color: var(--muted); font-size: 14px; margin: 2px 0 18px; max-width: 960px; }

