1	/* Sundown — 下线执行台
2	 * 状态机 + 渲染。数据来自 data.js（window.RUNBOOK，内联）。
3	 * 状态完备性（H-07）：
4	 *  loading —— 首屏同步渲染，无加载态（数据内联，代码路径保留于 mount 兜底）
5	 *  empty   —— RUNBOOK 缺失/为空时的空态面板（防御分支）
6	 *  ready   —— 主工作态
7	 *  selected—— 左轨选中已完成步骤，进入只读回看
8	 *  error   —— 强确认输入不匹配的内联错误态；非法动作一律禁用（零失误护栏）
9	 */
10	(function () {
11	  'use strict';
12	
13	  var RB = window.RUNBOOK;
14	  var app = document.getElementById('app');
15	  var TOKEN = RB && RB.confirmToken;
16	
17	  /* ---------- 展平步骤 ---------- */
18	  var STEPS = [];
19	  if (RB && RB.phases) {
20	    RB.phases.forEach(function (ph, pi) {
21	      ph.steps.forEach(function (st) {
22	        STEPS.push({
23	          id: st.id,
24	          title: st.title,
25	          desc: st.desc,
26	          why: st.why || '',
