426	      var si = parseInt(el.getAttribute('data-step'), 10);
427	      var txt = S.steps[si].confirmText;
428	      var bad = txt.length > 0 && txt.trim().toUpperCase() !== TOKEN;
429	      if (bad !== S.steps[si].mismatch) { S.steps[si].mismatch = bad; render(); }
430	    }
431	  });
432	
433	  app.addEventListener('input', function (ev) {
434	    var el = ev.target;
435	    if (el.classList && el.classList.contains('confirm-input')) {
436	      var i = parseInt(el.getAttribute('data-step'), 10);
437	      S.steps[i].confirmText = el.value;
438	      S.steps[i].mismatch = false;
439	      var match = el.value.trim().toUpperCase() === TOKEN;
440	      var btn = app.querySelector('[data-action="execute"][data-step="' + i + '"]');
441	      if (btn) btn.disabled = !match;
442	    }
443	  });
444	
445	  function doExecute(i) {
446	    var st = S.steps[i], step = STEPS[i];
447	    if (!checksAllDone(i)) return;              // 护栏：检查未过禁止执行
448	    if (step.irreversible && st.confirmText.trim().toUpperCase() !== TOKEN) {
449	      st.mismatch = true;                       // 护栏：强确认不匹配 → error 态
450	      return;
451	    }
452	    if (step.irreversible) {
453	      st.status = 'executed';
454	      st.windowEnd = Date.now() + step.windowSec * 1000;
455	      pushLog(i, '确认执行（已手输 ' + TOKEN + '）——进入 ' + step.windowSec + 's 恢复窗口');
456	      st.armed = false; st.confirmText = '';
457	    } else {
458	      st.status = 'retained';
459	      pushLog(i, '执行完成：' + step.actionLabel);
460	      advanceIf(i);
461	    }
462	  }
463	
464	  function advanceIf(i) {
465	    if (S.steps[i].status !== 'retained') return; // 护栏：只有保留态才解锁下一步
466	    if (i + 1 < TOTAL && S.steps[i + 1].status === 'locked') {
467	      S.steps[i + 1].status = 'ready';
468	    }
469	    if (allRetained()) S.finishedAt = Date.now();
470	  }
471	
472	  /* ---------- 心跳：倒计时与到期 ---------- */
473	  setInterval(function () {
474	    var now = Date.now(), dirty = false;
475	    S.steps.forEach(function (st, i) {
476	      if (st.status === 'executed' && now >= st.windowEnd) {
477	        st.status = 'retained';
478	        st.windowEnd = 0;
479	        pushLog(i, '恢复窗口到期，自动保留');
480	        dirty = true;
481	      }
482	    });
483	    if (dirty) {
484	      for (var k = 0; k < TOTAL; k++) advanceIf(k);
485	      render();
486	      return;
487	    }
488	    updateTickTexts();
489	  }, 250);
490	
491	  /* ---------- 焦点追踪（键盘可达性） ---------- */
492	  app.addEventListener('focusin', function (ev) {
493	    var el = ev.target.closest ? ev.target.closest('[data-fkey]') : null;
494	    if (el) S.focusKey = el.getAttribute('data-fkey');
495	  });
496	
497	  /* ---------- 首屏同步渲染：加载即就绪 ---------- */
498	  render();
499	})();
